// Slice: 01-crd-completion-happy-path
// Given a YAML document with apiVersion: argoproj.io/v1alpha1, kind: Application, spec: <cursor>
// And yaml.crdCatalog.enabled is true
// When I trigger completion at <cursor>
// Then I receive completion items for Application spec properties (e.g., "destination", "source", "project")

import { setupLanguageService, setupSchemaIDTextDocument } from './utils/testHelper';
import { ServiceSetup } from './utils/serviceSetup';
import { SettingsState, TextDocumentTestManager } from '../src/yamlSettings';
import { LanguageService } from '../src';
import { LanguageHandlers } from '../src/languageserver/handlers/languageHandlers';
import { Position } from 'vscode-languageserver-types';
import { expect } from 'chai';

describe('CRD Completion Tests', () => {
  let languageSettingsSetup: ServiceSetup;
  let languageService: LanguageService;
  let languageHandler: LanguageHandlers;
  let yamlSettings: SettingsState;

  before(() => {
    languageSettingsSetup = new ServiceSetup().withCompletion();
    const {
      languageService: langService,
      languageHandler: langHandler,
      yamlSettings: settings,
    } = setupLanguageService(languageSettingsSetup.languageSettings);
    languageService = langService;
    languageHandler = langHandler;
    yamlSettings = settings;
  });

  describe('Happy Path', () => {
    it('returns completion items for ArgoCD Application spec properties', async () => {
      const content = [
        'apiVersion: argoproj.io/v1alpha1',
        'kind: Application',
        'spec:',
        '  ',
      ].join('\n');

      const testTextDocument = setupSchemaIDTextDocument(content);
      yamlSettings.documents = new TextDocumentTestManager();
      (yamlSettings.documents as TextDocumentTestManager).set(testTextDocument);

      const result = await languageHandler.completionHandler({
        position: Position.create(3, 2), // After "spec:" on the next line
        textDocument: testTextDocument,
      });

      expect(result.items.length).to.be.greaterThan(0);
      const labels = result.items.map((item) => item.label);
      expect(labels).to.include('destination');
      expect(labels).to.include('source');
      expect(labels).to.include('project');
    });
  });
});


