  detectCRD(doc: JSONDocument): { apiVersion: string; kind: string } | null {
    if (!doc || !doc.root) {
      return null;
    }

    const root = doc.root;
    let apiVersion: string | undefined;
    let kind: string | undefined;

    if (root.type === 'object' && root.properties) {
      for (const prop of root.properties) {
        if (prop.keyNode.value === 'apiVersion' && prop.valueNode?.type === 'string') {
          apiVersion = prop.valueNode.value;
        }
        if (prop.keyNode.value === 'kind' && prop.valueNode?.type === 'string') {
          kind = prop.valueNode.value;
        }
      }
    }

    if (apiVersion && kind) {
      return { apiVersion, kind };
    }

    return null;
  }
}

