    schemaProvider.deleteSchema('https://crd-catalog.example.com/argoproj.io/v1alpha1/Application.json');
    schemaProvider.deleteSchema('file:///test-crd.yaml');
  });

  function parseSetup(content: string): Promise<Diagnostic[]> {
    const testTextDocument = setupSchemaIDTextDocument(content, 'file:///test-crd.yaml');
    yamlSettings.documents = new TextDocumentTestManager();
    (yamlSettings.documents as TextDocumentTestManager).set(testTextDocument);
    return validationHandler.validateTextDocument(testTextDocument);
  }

  describe('Happy Path', () => {
    it('reports type error when CRD property has incorrect type', async () => {
      // Given an ArgoCD Application schema in the CRD catalog
      const crdSchemaURL = 'https://crd-catalog.example.com/argoproj.io/v1alpha1/Application.json';
      schemaProvider.addSchemaWithUri('file:///test-crd.yaml', crdSchemaURL, {
        type: 'object',
        properties: {
          apiVersion: { type: 'string' },
          kind: { type: 'string' },
          spec: {
            type: 'object',
            properties: {
              destination: {
                type: 'object',
                properties: {
                  server: { type: 'string' },
                },
              },
            },
          },
        },
      });

      // And a YAML document with ArgoCD Application with type error
      const content = `apiVersion: argoproj.io/v1alpha1
kind: Application
spec:
  destination:
    server: 123`;

      // When the document is validated
      const result = await parseSetup(content);

      // Then a diagnostic is reported for incorrect type
      expect(result.length).to.be.greaterThan(0);
      const typeError = result.find((d) => d.message.includes('Incorrect type'));
      expect(typeError).to.not.be.undefined;
      expect(typeError.message).to.include('"string"');
    });
  });
});


