    // Check for CRD catalog
    if (this.crdCatalogConfig?.enabled) {
      const crd = this.detectCRD(doc);
      if (crd) {
        const crdSchemaURL = this.buildCRDCatalogURL(this.crdCatalogConfig.url, crd.apiVersion, crd.kind);
        return resolveSchemaForResource([crdSchemaURL]).then(
          (schema) => {
            // If schema has errors (e.g., 404), gracefully fallback to no schema
            if (schema.errors && schema.errors.length > 0) {
              return Promise.resolve(null);
            }
            return schema;
          },
          () => {
            // On any error, gracefully fallback to no schema
            return Promise.resolve(null);
          }
        );
